package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.DefaultMaxAgeVO;

class DefaultMaxAgeValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of default max age of oauth client")
  void test_default_max_age_value_holder_assign_plain_value() {
    Object holder = new Object();
    DefaultMaxAgeValueHolder<Object> value = new DefaultMaxAgeValueHolder<>(holder);
    Assertions.assertSame(holder, value.defaultMaxAge(1), "Setters must return the holder");
    Assertions.assertTrue(value.getDefaultMaxAgeValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getDefaultMaxAge().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.defaultMaxAgeNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getDefaultMaxAgeValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getDefaultMaxAge().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of default max age of oauth client")
  void test_default_max_age_value_holder_assign_value_object() {
    Object holder = new Object();
    DefaultMaxAgeValueHolder<Object> value = new DefaultMaxAgeValueHolder<>(holder);
    DefaultMaxAgeVO vo = DefaultMaxAgeVO.from(1);
    Assertions.assertFalse(value.getDefaultMaxAgeValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.defaultMaxAge(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getDefaultMaxAgeValue().orElseThrow());
    Assertions.assertSame(holder, value.defaultMaxAge(Optional.empty()));
    Assertions.assertFalse(value.getDefaultMaxAgeValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.defaultMaxAge(Optional.of(vo)));
    Assertions.assertSame(vo, value.getDefaultMaxAgeValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of default max age of oauth client against the original")
  void test_default_max_age_value_holder_read() {
    Object holder = new Object();
    DefaultMaxAgeValueHolder<Object> value = new DefaultMaxAgeValueHolder<>(holder);
    DefaultMaxAgeVO vo = DefaultMaxAgeVO.from(1);
    DefaultMaxAgeVO other = DefaultMaxAgeVO.from(1);
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getDefaultMaxAgeValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readDefaultMaxAge(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readDefaultMaxAge(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.defaultMaxAge(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readDefaultMaxAge(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readDefaultMaxAge(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of default max age of oauth client")
  void test_default_max_age_value_holder_unset() {
    Object holder = new Object();
    DefaultMaxAgeValueHolder<Object> value = new DefaultMaxAgeValueHolder<>(holder);
    DefaultMaxAgeVO vo = DefaultMaxAgeVO.from(1);
    value.defaultMaxAge(vo);
    Assertions.assertSame(holder, value.unsetDefaultMaxAgeIfMatches("defaultMaxAge_other"));
    Assertions.assertTrue(value.getDefaultMaxAgeValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetDefaultMaxAgeIfMatches("defaultMaxAge"));
    Assertions.assertFalse(value.getDefaultMaxAgeValue().isPresent(),
        "The field name must clear the value");
    value.defaultMaxAge(vo);
    Assertions.assertSame(holder, value.unsetDefaultMaxAge());
    Assertions.assertFalse(value.getDefaultMaxAgeValue().isPresent(), "Unset must clear the value");
  }
}
